    end

    field :user_documentation_implementation, ::Types::ImplementationStatusType, null: true do
      description <<~TEXT
      Technical user documentation. Public documentation that meaningfully describes the process users to
      install, configure, maintain, and troubleshoot the code for running the service. OR, in the case of
      those services not reliant on client installs, documentation that meaningfully describes how users
      perform tasks on the platform to utilise the service.
      TEXT
    end

    field :values_frameworks, [::Types::ValuesFrameworkType, { null: false }], null: false do
